const suffixRe = /\b(llc|inc|incorporated|corp|corporation|co|company|ltd|lp|llp|group|services|construction|builders|contracting|enterprises|logistics|trucking|transport|usa|management|design|developers|holdings)\b/gi;
const candidates = new Set();

for (const item of $input.all()) {
  const rawName = String(item.json.contractor_company || item.json.legal_name || '').trim();
  if (!rawName) continue;
  const cleanFull = rawName.toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
  const core = cleanFull.replace(suffixRe, '').replace(/\s+/g, '');
  const compact = cleanFull.replace(/\s+/g, '');
  if (core.length >= 4 && core.length <= 28) candidates.add(`${core}.com`);
  if (compact.length >= 4 && compact.length <= 28 && compact !== core) candidates.add(`${compact}.com`);
}

const domains = [...candidates].slice(0, 30);
return [{ json: { domains: domains.length ? domains : ['henselphelps.com', 'shopify.com'] } }];

